import{c as s,Q as n,j as l,m as e}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Claude Fable 5全网最全使用指南：从入门到榨干","description":"","frontmatter":{"url":"https://x.com/noahduck283/status/2072860039862497328","title":"Claude Fable 5全网最全使用指南：从入门到榨干","author":"诺鸭船长","archived":"2026-07-03T00:00:00.000Z","handle":"@noahduck283","published":"2026-07-03T00:00:00.000Z","stats":"134 likes · 20 retweets · 234 bookmarks · 54966 views","tags":["fable5","model-routing","prompt-template","cost-control","zh-cn","agentic-coding"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-03-@noahduck283-497328.md","filePath":"research/tweets/2026-07-03-@noahduck283-497328.md","lastUpdated":1785909234000}'),t={name:"research/tweets/2026-07-03-@noahduck283-497328.md"};function i(o,a,r,p,d,c){return n(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="claude-fable-5全网最全使用指南-从入门到榨干-—-noahduck283" tabindex="-1">Claude Fable 5全网最全使用指南：从入门到榨干 — @noahduck283 <a class="header-anchor" href="#claude-fable-5全网最全使用指南-从入门到榨干-—-noahduck283" aria-label="Permalink to &quot;Claude Fable 5全网最全使用指南：从入门到榨干 — @noahduck283&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/noahduck283/status/2072860039862497328" target="_blank" rel="noreferrer">https://x.com/noahduck283/status/2072860039862497328</a><strong>作者</strong>：诺鸭船长（@noahduck283） <strong>發布日期</strong>：2026-07-03 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article（簡體中文） <strong>統計</strong>：134 likes · 20 retweets · 234 bookmarks · 54966 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>你第一次打开 Fable 5，最容易犯的错，是把它当成一个更强版opus。 这样用，很快就会难受。小任务上，它贵得没必要；硬任务上，你又不知道怎么判断它到底有没有做完。它很主动，会自己想办法跑验证，会把一个看起来两行 CSS 就能修掉的 bug 拆成一条很长的调查链路。它也确实贵，官方 API 价格是每百万输入 token（模型读写内容时消耗的计量单位）10 美元、每百万输出 token 50 美元。长程 agent 一旦开始读文件、跑测试、看日志，账单不是按&quot;回答一次&quot;算，而是按&quot;一段工程流程&quot;算。</p><p>所以这篇不写模型排行榜。更重要的是：什么时候该上 Fable，什么时候别浪费钱；怎么用 Claude Code、API 或 ZenMux 先跑几组真实任务；怎么记录成本、fallback（模型回退，也就是换别的模型接手）和返工量，最后把它放进&quot;少数硬任务升级到 Fable，多数日常任务继续用便宜模型&quot;的工作流里。</p><h1 id="一、先看它能不能把任务跑完" tabindex="-1">一、先看它能不能把任务跑完 <a class="header-anchor" href="#一、先看它能不能把任务跑完" aria-label="Permalink to &quot;一、先看它能不能把任务跑完&quot;">​</a></h1><p>Fable 5 更适合把一件麻烦事从头跟到尾。普通模型更像一个回答问题的人。你问它，它答；你追问，它再答。Fable 5 更像一个能接工单的高级助手：它会先看目标，再读上下文，拆步骤，动手验证，发现不对还会往回查。</p><p>Fable 5 最值得上的任务：多文件重构、带陷阱的 bug 修复、长上下文 PR review、多模态工程任务、自我验证任务（&quot;先给计划，改完后运行测试，失败就继续修&quot;）。</p><p>不适合的任务：普通问答、短代码片段、低价值批量文案。</p><p>Fable 5 与 Mythos 5 区分：Fable 5 是公开版本，带 classifier（安全分类器）；Mythos 5 面向受限访问，不能把 Mythos 能力直接算进 Fable 5 头上。</p><h1 id="二、入口怎么选" tabindex="-1">二、入口怎么选 <a class="header-anchor" href="#二、入口怎么选" aria-label="Permalink to &quot;二、入口怎么选&quot;">​</a></h1><p>四类入口：</p><ol><li>Claude 官方产品（Claude.ai / Desktop / Mobile / Claude Code）— 适合快速试水</li><li>Claude API（model ID: <code>claude-fable-5</code>，默认 1M context，最高 128k output）— 适合 agent/CI/评测脚本</li><li>Claude Code / Cursor — 最容易展示价值（读仓库、改文件、跑命令）</li><li>ZenMux 等多模型聚合平台 — 适合横评（PK 模式、成本/延迟对比）</li></ol><h1 id="三、什么活值得交给它-硬、长、脏" tabindex="-1">三、什么活值得交给它：硬、长、脏 <a class="header-anchor" href="#三、什么活值得交给它-硬、长、脏" aria-label="Permalink to &quot;三、什么活值得交给它：硬、长、脏&quot;">​</a></h1><ul><li><strong>硬</strong>：验收标准明确，不能靠漂亮话过关（测试通过/类型错误消失/PR 需给文件级证据）</li><li><strong>长</strong>：上下文多、步骤多（跨几十个文件的重构、多轮调试）</li><li><strong>脏</strong>：任务现场不干净（文档过期、测试偶发失败、依赖版本乱）</li></ul><h1 id="四、别写聊天-prompt-把需求写成一张工单" tabindex="-1">四、别写聊天 prompt：把需求写成一张工单 <a class="header-anchor" href="#四、别写聊天-prompt-把需求写成一张工单" aria-label="Permalink to &quot;四、别写聊天 prompt：把需求写成一张工单&quot;">​</a></h1><p>一个好任务包至少包含六件事：<strong>目标、上下文、硬约束、可操作权限、验收标准、汇报格式</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你要处理一个真实工程任务，不要只给建议。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标：</span></span>
<span class="line"><span>【写清要完成的工程目标】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>上下文：</span></span>
<span class="line"><span>【仓库、相关目录、错误日志、截图、issue、已有尝试】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>硬约束：</span></span>
<span class="line"><span>1. 不要改公共 API，除非先说明原因。</span></span>
<span class="line"><span>2. 不要引入新依赖，除非先解释收益和风险。</span></span>
<span class="line"><span>3. 每次修改后运行相关测试。</span></span>
<span class="line"><span>4. 如果证据不足，先说明你还需要检查什么。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>允许操作：</span></span>
<span class="line"><span>【读文件 / 改文件 / 跑测试 / 启动本地服务 / 截图 / 访问网络】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>验收标准：</span></span>
<span class="line"><span>1. 【测试命令】通过。</span></span>
<span class="line"><span>2. 【用户可见问题】消失。</span></span>
<span class="line"><span>3. 输出变更摘要、验证记录、未覆盖风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最后输出：</span></span>
<span class="line"><span>- Root cause</span></span>
<span class="line"><span>- Files changed</span></span>
<span class="line"><span>- Verification</span></span>
<span class="line"><span>- Remaining risks</span></span></code></pre></div><h1 id="五、横评要看返工量-不看漂亮话" tabindex="-1">五、横评要看返工量，不看漂亮话 <a class="header-anchor" href="#五、横评要看返工量-不看漂亮话" aria-label="Permalink to &quot;五、横评要看返工量，不看漂亮话&quot;">​</a></h1><p>一组合格的 PK 至少记录：模型名称、任务类型、是否 fallback、首字速度、总耗时、token 消耗、实际费用、是否运行测试、<strong>人工返工量</strong>。</p><p>三组对照推荐：</p><ul><li>Fable 5 vs Opus 4.8（看多值多少）</li><li>Fable 5 vs GPT/Gemini（跨模型能力差异）</li><li>Fable 5 vs 便宜模型组合（路由策略价值）</li></ul><h1 id="六、成本控制" tabindex="-1">六、成本控制 <a class="header-anchor" href="#六、成本控制" aria-label="Permalink to &quot;六、成本控制&quot;">​</a></h1><ul><li>给预算闸门（每任务 10min 或某 token 上限）</li><li>分层路由（日常→便宜模型；硬任务→Fable）</li><li>记录人工返工量（模型花 $12 但只需 review 20min，可能很值）</li><li>拆任务（定位/方案/修改/验证四段，每段有停止点）</li><li>清上下文（无关日志、过期文档先清掉）</li></ul><p>Simon Willison CSS bug 案例：复现+验证链路约 $12，但找到根因省了大量调试时间。</p><h1 id="七、上手前三条红线" tabindex="-1">七、上手前三条红线 <a class="header-anchor" href="#七、上手前三条红线" aria-label="Permalink to &quot;七、上手前三条红线&quot;">​</a></h1><ol><li><strong>Fallback</strong>：安全/漏洞/供应链任务可能触发 fallback，要单独记录是否真的是 Fable 在回答</li><li><strong>数据保留</strong>：Mythos-class 模型输入输出保留 30 天（安全工作），不训练新模型，但企业私有数据要脱敏</li><li><strong>Sandbox</strong>：Fable 会跑命令、启动服务、写临时文件，用测试账号/低权限目录/无生产密钥环境</li></ol><h1 id="八、日常分层" tabindex="-1">八、日常分层 <a class="header-anchor" href="#八、日常分层" aria-label="Permalink to &quot;八、日常分层&quot;">​</a></h1><ul><li>日常层：便宜模型（问答/短代码/简单脚本）</li><li>工作层：Opus/Sonnet（一般 bug/普通 PR review/小重构）</li><li>硬任务层：Fable（跨模块迁移/复杂调试/长 PR/多模态/自我验证）</li></ul><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Fable 5 是&quot;硬/長/髒&quot;任務專用，提供完整工單格式 prompt 模板，分層路由策略（日常→便宜模型，硬任務→Fable）；注意 30 天數據保留和 fallback 記錄。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>Fable 5 = 硬任務模型（跨文件重構/複雜 bug/長 PR review/自我驗證）</li><li>工單格式六元素：目標+上下文+硬約束+允許操作+驗收標準+彙報格式</li><li>橫評應看「人工返工量」而非「漂亮話」</li><li>Fable 帶 classifier，安全邊界任務需記錄是否 fallback</li><li>Mythos-class 30 天數據保留（企業私有數據先脫敏）</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Fable 5 API 定價：$10/M input tokens，$50/M output tokens</li><li>model ID：<code>claude-fable-5</code>，context 1M，output 最高 128k</li><li>Simon Willison CSS bug 案例：$12 完成復現+驗證</li><li>分層：日常(haiku) → 工作(opus/sonnet) → 硬任務(fable)</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>工單格式 prompt 模板是本文最高價值，可直接提取為 SKILL/Rule</li><li>文章含 ZenMux 推廣動機，中立性有限</li><li>「硬/長/髒」三特徵框架是好的任務分類啟發式，但無量化邊界</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>工單 prompt 模板 + 分層路由策略可直接套用</td></tr><tr><td>B. 創新性 (20%)</td><td>6.5/10</td><td>硬/長/髒三特徵框架是好的歸納，但大多為既知整合</td></tr><tr><td>C. 證據品質 (20%)</td><td>6.5/10</td><td>Simon Willison 案例有具體數字；ZenMux 推廣影響中立性</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>fallback/30天保留/sandbox 細節有深度，工單模板具體</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>分層路由原則跨模型通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.8/10</strong></td><td>7×0.3+6.5×0.2+6.5×0.2+7×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：工單格式六元素模板和「硬/長/髒」任務判斷啟發式可補充 delegation-protocol.md；30 天數據保留和 fallback 記錄補充 security-hygiene.md。</p>`,43)])])}const b=s(t,[["render",i]]);export{u as __pageData,b as default};
